WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_average_current'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '现期平均数', 'kp-xingce-data-average-current', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "现期平均数"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总数除以份数的绝对量指标，关键在于快速找准谁是分子、谁是分母。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干中出现“平均”、“均”、“每”等字眼，要求计算当前的平均水平。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式与语感判定"}]}, {"type": "katexBlock", "attrs": {"content": "平均数 = \\frac{总数}{份数} = \\frac{A}{B}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "三大常见句型（秒定分子分母）："}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“求 每B的A”：每字后面是分母，即 A/B。如“每平方米的产量” = 产量 / 面积。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“求 单位B的A”：单位后面是分母，同上。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“求 A的平均B”：反向表达，A是分母，B是分子，即 B/A。如“某商场的日均客流量” = 客流量 / 天数。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干圈出均/每/单位] --> B[利用语感判定找出分子 A 和 分母 B]\nB --> C[回材料定位现期量 A 和 B]\nC --> D{分母是否属于常识隐藏项?}\nD -- 是(如日均/月均) --> E[自行根据常识补全分母(如12个月/365天)]\nD -- 否 --> F[直接套用材料给出的数值]\nE --> G[截位直除得出答案]\nF --> G"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某地苹果总产量 45000 吨，种植总面积 1500 公顷。求该地苹果的单位面积产量是多少吨/公顷？选项：A. 15  B. 20  C. 30  D. 45"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找句型：“单位面积产量”。“单位”后面是“面积”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定分母：面积是分母，产量是分子。即 产量 / 面积。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列式：45000 ÷ 1500。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算：直接削去两个零，450 ÷ 15 = 30。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "致命陷阱：隐藏分母与常识坑", "marks": [{"type": "bold"}]}, {"type": "text", "text": "求“月均产量”时，分母是隐藏的数字 12；求“日均产量”时，必须看清这一年是平年（365天）还是闰年（366天），月份是大月（31天）还是小月（30天）。材料里绝对不会给你写出来这些天数！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "每次做到“每”字题，拿笔在“每”后面的词划个底线，强迫自己把它放到分母位置。"}]}]}$$ AS jsonb), NULL, '现期平均数的核心考点与实战推导。', category_node.id, CAST('["资料分析", "现期平均数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_average_current", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
